export const VIDEO_STYLES={balanced:'Умный монтаж — по содержанию',automotive:'Автообзор — экстерьер, салон, детали','saas-motion':'SaaS motion — интерфейсы и анимация',ugc:'UGC — человек и продукт',editorial:'Редакционный — сдержанная подача'};
export function motionSettings(v={}){return {features:(Array.isArray(v.features)?v.features:[]).filter(x=>typeof x==='string'&&x.trim()).slice(0,3).map(x=>x.slice(0,30)),useSource:v.useSource===true,enabled:v.enabled===true,kind:['intro','interface','benefits','cta'].includes(v.kind)?v.kind:'interface',product:String(v.product||'Ваш продукт').slice(0,80),accent:/^#[a-f0-9]{6}$/i.test(v.accent||'')?v.accent:'#c3f547'};}
const box=(ctx,x,y,w,h,r,color)=>{ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()};
export function drawMotionScene(ctx,canvas,clip,offset,source){const s=motionSettings(clip.motionDesign),features=s.features.length?s.features:['Идея','Детали','Результат'],w=canvas.width,h=canvas.height,unit=Math.min(w,h),p=Math.min(1,offset/.65),ease=1-Math.pow(1-p,3),vertical=h>w;ctx.save();ctx.fillStyle='#080b0b';ctx.fillRect(0,0,w,h);const glow=ctx.createRadialGradient(w*.7,h*.55,0,w*.7,h*.55,w*.8);glow.addColorStop(0,s.accent+'45');glow.addColorStop(1,'#080b0b00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#ffffff0a';ctx.lineWidth=1;for(let x=0;x<w;x+=unit*.09){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=unit*.09){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.fillStyle='#e9efee';ctx.font=`600 ${unit*.028}px "Golos Text"`;ctx.fillText(s.product,w*.08,h*.1,w*.84);ctx.translate(w/2,h*.48+(1-ease)*unit*.12);ctx.rotate(Math.sin(offset*.5)*.015);ctx.scale(.88+.12*ease,.88+.12*ease);const cw=w*(vertical?.82:.68),ch=h*(vertical?.4:.56),x=-cw/2,y=-ch/2;ctx.shadowColor='#000';ctx.shadowBlur=unit*.06;box(ctx,x,y,cw,ch,unit*.025,'#1d2424');ctx.shadowBlur=0;box(ctx,x+unit*.015,y+unit*.015,cw-unit*.03,ch-unit*.03,unit*.018,'#f1f3ee');ctx.fillStyle='#a7ada5';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(x+unit*.04+i*unit*.023,y+unit*.045,unit*.006,0,Math.PI*2);ctx.fill()}box(ctx,x+cw*.06,y+ch*.16,cw*.2,ch*.73,unit*.012,'#e1e7dc');box(ctx,x+cw*.09,y+ch*.22,cw*.13,ch*.07,unit*.007,s.accent);for(let i=0;i<4;i++)box(ctx,x+cw*.09,y+ch*(.36+i*.11),cw*.12,ch*.025,unit*.003,'#aeb9a7');const bx=x+cw*.31,by=y+ch*.19,bw=cw*.62;box(ctx,bx,by,bw,ch*.18,unit*.012,'#17221a');ctx.fillStyle='#f1f4ed';ctx.font=`600 ${unit*.025}px "Golos Text"`;ctx.fillText(s.kind==='cta'?'Начните с одного шага':s.kind==='benefits'?'Всё нужное — рядом':s.kind==='intro'?'От идеи — к результату':'Рабочее пространство',bx+bw*.06,by+ch*.1,bw*.9);for(let i=0;i<3;i++){const reveal=Math.min(1,Math.max(0,(offset-i*.13)/.6)),yy=by+ch*.27+i*ch*.17;box(ctx,bx+(1-reveal)*cw*.05,yy,bw,ch*.13,unit*.012,i===1?s.accent:'#d9e2d2');ctx.fillStyle='#56644e';ctx.font=`500 ${unit*.018}px "Golos Text"`;ctx.fillText(features[i%features.length],bx+bw*.06,yy+ch*.08,bw*.75)}if(source&&clip.motionDesign?.useSource){ctx.save();ctx.beginPath();ctx.roundRect(bx,by,bw,ch*.65,unit*.01);ctx.clip();ctx.drawImage(source,bx,by,bw,ch*.65);ctx.restore()}const cursorX=x+cw*(.57+.12*Math.sin(offset*.7)),cursorY=y+ch*(.55+.15*Math.cos(offset*.8));ctx.fillStyle='#111';ctx.beginPath();ctx.moveTo(cursorX,cursorY);ctx.lineTo(cursorX+unit*.01,cursorY+unit*.04);ctx.lineTo(cursorX+unit*.02,cursorY+unit*.025);ctx.lineTo(cursorX+unit*.04,cursorY+unit*.02);ctx.closePath();ctx.fill();ctx.restore();ctx.save();if(s.kind==='intro'){ctx.fillStyle='#f0f5ee';ctx.font=`700 ${unit*.055}px "Golos Text"`;ctx.fillText('От идеи к результату',w*.08,h*.2,w*.84)}if(s.kind==='cta'){box(ctx,w*.12,h*.72,w*.76,h*.065,unit*.018,s.accent);ctx.fillStyle='#12200c';ctx.font=`700 ${unit*.033}px "Golos Text"`;ctx.fillText('Попробовать '+s.product,w*.17,h*.762,w*.66)}if(s.kind==='benefits'){box(ctx,w*.51,h*.25,w*.39,h*.085,unit*.02,s.accent);ctx.fillStyle='#17240f';ctx.font=`600 ${unit*.023}px "Golos Text"`;ctx.fillText(features[0],w*.55,h*.3,w*.32)}ctx.restore();}
export async function createMotionFile(product){const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=720;drawMotionScene(canvas.getContext('2d'),canvas,{motionDesign:{enabled:true,product}},1,null);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));return new File([blob],'SaaS-motion-концепт.png',{type:'image/png'});}

export function motionFeatures(topic,provided){if(Array.isArray(provided)&&provided.length)return provided.slice(0,3).map(s=>String(s).slice(0,30));const features=[];for(const [re,label]of [[/монтаж/i,'Монтаж'],[/титр/i,'Субтитры'],[/обложк/i,'Обложка'],[/заказ/i,'Заказы'],[/аналит/i,'Аналитика'],[/отч[её]т/i,'Отчёты'],[/проект/i,'Проекты'],[/команд/i,'Команда']])if(re.test(topic))features.push(label);return features.length?features.slice(0,3):['Ваша идея','Рабочий процесс','Готовый результат'];}
